package beer

import (
	"errors"
	"fmt"
	"strings"
)

func Song() string {
	song, err := Verses(99, 0)
	if err != nil {
		panic(err)
	}
	return song
}

func Verses(start, stop int) (string, error) {
	if start > 99 || stop < 0 || start < stop {
		return "", errors.New("invalid verse range")
	}
	var sb strings.Builder
	for n := start; n >= stop; n-- {
		verse, err := Verse(n)
		if err != nil {
			return "", err
		}
		sb.WriteString(verse)
	}
	return sb.String(), nil
}

func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", errors.New("invalid verse number")
	}
	if n == 0 {
		return verse0, nil
	}
	if n == 1 {
		return verse1, nil
	}
	return fmt.Sprintf("%d bottles of beer on the wall, %d bottles of beer.\n"+
		"Take one down and pass it around, %d bottles of beer on the wall.\n",
		n, n, n-1), nil
}

const verse1 = "1 bottle of beer on the wall, 1 bottle of beer.\n" +
	"Take it down and pass it around, no more bottles of beer on the wall.\n"

const verse0 = "No more bottles of beer on the wall, no more bottles of beer.\n" +
	"Go to the store and buy some more, 99 bottles of beer on the wall.\n"

